  "claim": {
    "component_id": "C024",
    "value": "If multiple alignments fit, references conflict or overlap is insufficient, the alternatives should be retained.",
    "scope": "Handling of unresolved chronological alternatives under the stated conditions.",
    "provenance": {
      "refs": [
